135	    pub(crate) fn add_plugins_output(&mut self) {
136	        if !self.config.features.enabled(Feature::Plugins) {
137	            self.add_info_message(
138	                "Plugins are disabled.".to_string(),
139	                Some("Enable the plugins feature to use /plugins.".to_string()),
140	            );
141	            return;
142	        }
143	
144	        self.prefetch_plugins();
145	
146	        match self.plugins_cache_for_current_cwd() {
147	            PluginsCacheState::Ready(response) => {
148	                self.open_plugins_popup(&response);
149	            }
150	            PluginsCacheState::Failed(err) => {
151	                self.add_to_history(history_cell::new_error_event(err));
152	            }
153	            PluginsCacheState::Loading | PluginsCacheState::Uninitialized => {
154	                self.open_plugins_loading_popup();
155	            }
156	        }
157	        self.request_redraw();
158	    }
