179	                if !auth_flow_active {
180	                    self.refresh_plugins_popup_if_open(&response);
181	                }
182	            }
183	            Err(err) => {
184	                if !auth_flow_active {
185	                    self.plugins_fetch_state.cache_cwd = None;
186	                    self.plugins_cache = PluginsCacheState::Failed(err.clone());
187	                    let _ = self.bottom_pane.replace_selection_view_if_active(
188	                        PLUGINS_SELECTION_VIEW_ID,
189	                        self.plugins_error_popup_params(&err),
