fn is_curated_marketplace(marketplace: &PluginMarketplaceEntry) -> bool {
    marketplace.name == OPENAI_CURATED_MARKETPLACE_NAME
}

/// Unique tab identifier for a marketplace-specific tab, derived from the
/// marketplace's file system path so tabs with duplicate display names remain
/// individually addressable.
fn marketplace_tab_id(marketplace: &PluginMarketplaceEntry) -> String {
    format!("marketplace:{}", marketplace.path.display())
}

/// Tab label for a marketplace, adding a `Name (K/N)` disambiguating suffix
/// when more than one marketplace in `marketplaces` shares the same display
/// name.
fn marketplace_tab_label(
    marketplace: &PluginMarketplaceEntry,
    marketplaces: &[&PluginMarketplaceEntry],
    idx: usize,
) -> String {
    let display_name = marketplace_display_name(marketplace);
    let total = marketplaces
        .iter()
        .filter(|other| marketplace_display_name(other) == display_name)
        .count();
    if total <= 1 {
        return display_name;
    }
    let occurrence = marketplaces
        .iter()
        .take(idx + 1)
        .filter(|other| marketplace_display_name(other) == display_name)
        .count();
    format!("{display_name} ({occurrence}/{total})")
}

/// Collect `(marketplace, plugin, display_name)` tuples for the plugins that
/// match `predicate`, sorted installed-first then alphabetically by name.
fn sorted_plugin_entries<'a>(
    marketplaces: &[&'a PluginMarketplaceEntry],
    predicate: impl Fn(&PluginSummary) -> bool,
) -> Vec<(&'a PluginMarketplaceEntry, &'a PluginSummary, String)> {
    let mut entries: Vec<(&PluginMarketplaceEntry, &PluginSummary, String)> = marketplaces
        .iter()
        .flat_map(|marketplace| {
            marketplace
                .plugins
                .iter()
                .filter(|plugin| predicate(plugin))
                .map(move |plugin| (*marketplace, plugin, plugin_display_name(plugin)))
        })
        .collect();
    entries.sort_by(|left, right| {
        right
            .1
            .installed
            .cmp(&left.1.installed)
            .then_with(|| left.2.to_ascii_lowercase().cmp(&right.2.to_ascii_lowercase()))
            .then_with(|| left.2.cmp(&right.2))
            .then_with(|| left.1.name.cmp(&right.1.name))
            .then_with(|| left.1.id.cmp(&right.1.id))
    });
    entries
